                if (nums[prev] > nums[curr]) {
                    return false;
                }
            }
            return true;
        };

        int ans = INT_MAX;

        // 从 0 开始向右是递增的
        if (check(1)) {
            // 直接旋转
            ans = min(ans, zero);

